    for u in reachable:
        row = {u: 0}
        for v, weight in graph.get(u, {}).items():
            if v in reachable:
                previous = row.get(v)
                if previous is None or weight < previous:
                    row[v] = weight
        matrix[u] = row

    def advance(distances, edges):
        result = {}
        for u, cost in distances.items():
            for v, weight in edges[u].items():
                candidate = cost + weight
                previous = result.get(v)
                if previous is None or candidate < previous:
                    result[v] = candidate
        return result

