    for u, v, _ in edges:
        graph[u].append(v)
        reverse[v].append(u)

    reachable = [False] * n
    reachable[source] = True
    stack = [source]
    while stack:
        u = stack.pop()
        for v in graph[u]:
            if not reachable[v]:
                reachable[v] = True
                stack.append(v)

    if not reachable[target]:
        return None

    can_reach_target = [False] * n
    can_reach_target[target] = True
    stack = [target]
    while stack:
        v = stack.pop()
        for u in reverse[v]:
            if not can_reach_target[u]:
                can_reach_target[u] = True
                stack.append(u)

    active = [v for v in range(n) if reachable[v] and can_reach_target[v]]
    index = {v: i for i, v in enumerate(active)}
    m = len(active)
    relevant_edges = [
        (index[u], index[v], w)
        for u, v, w in edges
        if reachable[u] and can_reach_target[v]
    ]

    bits = k.bit_length()
    direct_work = k * (len(relevant_edges) + m)
    matrix_work = bits * m * m * m

    if m <= 100 and direct_work > 4 * matrix_work:
        matrix = [[None] * m for _ in range(m)]
        for i in range(m):
            matrix[i][i] = 0
        for u, v, w in relevant_edges:
            old = matrix[u][v]
            if old is None or w < old:
                matrix[u][v] = w

        vector = [None] * m
