        while exponent:
            if exponent % 2:
                result = [None] * m
                for i in range(m):
                    x = vector[i]
                    if x is None:
                        continue
                    row = matrix[i]
                    for j in range(m):
                        y = row[j]
                        if y is not None:
                            value = x + y
                            if result[j] is None or value < result[j]:
                                result[j] = value
                vector = result

            exponent //= 2
            if exponent:
                squared = [[None] * m for _ in range(m)]
                for i in range(m):
                    out_row = squared[i]
                    row = matrix[i]
                    for mid in range(m):
                        x = row[mid]
